function getRuntimeActionRequestKey(e){switch(e.kind){case`load-skill`:return`runtime-action:${e.kind}:${e.callId}`;case`remote-agent-call`:return`subagent-call:${e.remoteAgentName}:${e.callId}`;case`subagent-call`:return`subagent-call:${e.subagentName}:${e.callId}`;case`tool-call`:return`tool-call:${e.toolName}:${e.callId}`}}function getPendingDispatchActionKey(e){switch(e.target.kind){case`remote-agent-call`:return`subagent-call:${e.target.remoteAgentName}:${e.callId}`;case`self-agent-call`:case`subagent-call`:return`subagent-call:${e.target.subagentName}:${e.callId}`;case`task-cancel`:case`task-update`:case`workflow-tool-call`:return`tool-call:${e.toolName}:${e.callId}`;default:return e.target}}function getRuntimeActionResultKey(e){switch(e.kind){case`load-skill-result`:return`runtime-action:load-skill:${e.callId}`;case`subagent-result`:return`subagent-call:${e.subagentName}:${e.callId}`;case`tool-result`:return`tool-call:${e.toolName}:${e.callId}`}}export{getPendingDispatchActionKey,getRuntimeActionRequestKey,getRuntimeActionResultKey};