import{createHash}from"node:crypto";import{deriveAgentOperationId}from"#harness/handles/operation-id.js";function deriveRootTurnActivityWorkId(e){return`root:${hashTuple([e.sessionId,e.turnId])}`}function deriveChildActivityWorkId(e){return`work:${deriveAgentOperationId(e)}`}function hashTuple(t){return createHash(`sha256`).update(JSON.stringify(t)).digest(`hex`)}export{deriveChildActivityWorkId,deriveRootTurnActivityWorkId};