import{resumeHook}from"#internal/workflow/runtime.js";import{HookNotFoundError}from"#compiled/@workflow/errors/index.js";async function forwardTurnCancellationStep(t){"use step";for(let n=0;n<50;n+=1)try{return await resumeHook(t.token,t.payload),!0}catch(e){if(!HookNotFoundError.is(e))throw e;if(n===49)return!1;await new Promise(e=>setTimeout(e,20))}return!1}export{forwardTurnCancellationStep};