import{createActionResultEvent,createActionsRequestedEvent}from"#protocol/message.js";import{createRuntimeActionRequestFromToolCall}from"#harness/runtime-actions.js";import{createRuntimeToolResultFromValue}from"#harness/action-result-helpers.js";async function emitWorkflowActionsRequested(e){for(let r of e.interrupts){let i={input:r.input,toolCallId:r.toolCallId,toolName:r.toolName,type:`tool-call`};await e.emit(createActionsRequestedEvent({actions:[createRuntimeActionRequestFromToolCall({toolCall:i,tools:e.tools})],sequence:e.emissionState.sequence,stepIndex:e.emissionState.stepIndex,turnId:e.emissionState.turnId}))}}async function emitWorkflowActionResults(t){for(let[n,i]of t.results.entries()){let a=t.interrupts[n];if(a===void 0)break;await t.emit(createActionResultEvent({result:createRuntimeToolResultFromValue({callId:a.toolCallId,isError:i.isError,output:i.output,toolName:a.toolName}),sequence:t.emissionState.sequence,stepIndex:t.emissionState.stepIndex,turnId:t.emissionState.turnId}))}}export{emitWorkflowActionResults,emitWorkflowActionsRequested};