import{createHash}from"node:crypto";function stableModuleId(t){let n=t.replaceAll(`\\`,`/`).replace(/[?#].*$/,``),r=n.lastIndexOf(`/node_modules/`);if(r>=0)n=n.slice(r+14);else{let e=process.cwd().replaceAll(`\\`,`/`);n.startsWith(`${e}/`)&&(n=n.slice(e.length+1))}return createHash(`sha256`).update(n).digest(`hex`).slice(0,32)}export{stableModuleId};